function physicsStep() {
  let n = 2;
  const vmax = maxSpeed();
  if (vmax > 1) n = Math.max(n, Math.ceil((vmax * STEP) / 0.07));
  if (n > 3) n = 3;
  const h = STEP / n;
  for (let i = 0; i < n; i++) micro(h);
  time += STEP;
  sampleAcc += STEP;
  if (sampleAcc >= 0.04) {
    sampleAcc = 0;
    const sp = car ? Math.hypot(car.vel.x, car.vel.y) : 0;
    samples.push(sp);
    if (samples.length > 240) samples.shift();
  }
}

function brickRGB(id, layer) {
  const n = (Math.imul(id + 3, 1103515245) + 12345) >>> 0;
  const shade = 1 - layer * 0.07;
  return [
    (146 + (n & 31)) * shade,
    (54 + ((n >> 5) & 18)) * shade,
    (40 + ((n >> 9) & 10)) * shade,
  ];
}

function readSettings() {
  settings.speed = clamp(Math.round(Number($("sSpeed").value) || 22), 5, 45);
  settings.cols = clamp(Math.round(Number($("sCols").value) || 12), 4, 24);
  settings.rows = clamp(Math.round(Number($("sRows").value) || 8), 3, 16);
  settings.layers = clamp(Math.round(Number($("sLayers").value) || 2), 1, 5);
  const mass = Math.round(Number($("sMass").value) * 10) / 10;
  settings.mass = clamp(mass || 2.5, 0.5, 12);
  $("sSpeed").value = String(settings.speed);
  $("sCols").value = String(settings.cols);
  $("sRows").value = String(settings.rows);
  $("sLayers").value = String(settings.layers);
  $("sMass").value = String(settings.mass);
  $("vSpeed").textContent = settings.speed + " m/s";
  $("vCols").textContent = String(settings.cols);
  $("vRows").textContent = String(settings.rows);
  $("vLayers").textContent = String(settings.layers);
  $("vMass").textContent = settings.mass.toFixed(1) + " kg";
}

function buildScene(launch) {
  readSettings();
  nextId = 1;
  bricks = [];

function buildScene(launch) {
  readSettings();
  nextId = 1;
  bricks = [];
  bodies = [];
  dust = [];
  skids = [];
  samples = [];
  sampleAcc = 0;
  contactCache = new Map();
  time = 0;
  acc = 0;
  quiet = 0;
  shake = 0;
  crumple = 0;
  moving = 0;
  impacted = false;
  impactSpeed = null;
  rngState = 20260922;
  pending = false;
  $("pending").textContent = "";

  const cols = settings.cols;
  const rows = settings.rows;
  const layers = settings.layers;
  const mass = settings.mass;
  const carX = 2.55;
  wallFront = carX + CAR_L * 0.5 + 4.05;
  const width = cols * BRICK_W;
  const z0 = -width * 0.5;

  car = makeBody(v3(carX, CAR_H * 0.5, 0), CAR_L * 0.5, CAR_H * 0.5, CAR_Z * 0.5, CAR_MASS, {
    isCar: true,
    mu: GROUND_MU,
    e: CAR_E,
    rgb: [194, 59, 50],
  });
  car.wheelW = [0, 0];
  if (launch) {
    car.vel.x = settings.speed;
    car.wheelW[0] = settings.speed / WHEEL_R;
    car.wheelW[1] = settings.speed / WHEEL_R;
  }

  for (let L = 0; L < layers; L++) {
    const x = wallFront + BRICK_D * (L + 0.5);
    for (let r = 0; r < rows; r++) {
      const y = BRICK_H * (r + 0.5);
      const stagger = ((L + r) & 1) === 1;
      if (!stagger) {
        for (let c = 0; c < cols; c++) {
          const z = z0 + BRICK_W * (c + 0.5);
          const b = makeBody(v3(x, y, z), BRICK_D * 0.5, BRICK_H * 0.5, BRICK_W * 0.5, mass, { layer: L });
          b.rgb = brickRGB(b.id, L);
          b.asleep = true;
          bricks.push(b);
        }
      } else {
        const halfM = mass * 0.5;
        const left = makeBody(v3(x, y, z0 + BRICK_W * 0.25), BRICK_D * 0.5, BRICK_H * 0.5, BRICK_W * 0.25, halfM, { layer: L });
        left.rgb = brickRGB(left.id, L);
        const right = makeBody(v3(x, y, z0 + width - BRICK_W * 0.25), BRICK_D * 0.5, BRICK_H * 0.5, BRICK_W * 0.25, halfM, { layer: L });
        right.rgb = brickRGB(right.id, L);
        left.asleep = true;
        right.asleep = true;
        bricks.push(left);
        for (let c = 0; c < cols - 1; c++) {
          const z = z0 + BRICK_W * (c + 1);
          const b = makeBody(v3(x, y, z), BRICK_D * 0.5, BRICK_H * 0.5, BRICK_W * 0.5, mass, { layer: L });
          b.rgb = brickRGB(b.id, L);
          b.asleep = true;
          bricks.push(b);
        }
        bricks.push(right);
      }
    }
  }
  bodies = [car, ...bricks];
  wallMass = cols * rows * layers * mass;
  running = !!launch;
  status = launch ? "LAUNCH" : "READY";
  focusX = carX + 1.6;
  $("wallStat").textContent = bricks.length + " bricks · " + wallMass.toLocaleString(undefined, { maximumFractionDigits: 1 }) + " kg";
  updateHud();
}

function updateHud() {
  const sp = car ? Math.hypot(car.vel.x, car.vel.y, car.vel.z) : 0;
  $("mSpeed").innerHTML = sp.toFixed(1) + "<em>m/s</em>";
  $("mTime").innerHTML = time.toFixed(2) + "<em>s</em>";

