      const p = B.verts[v];
      if (p.y > 0.01) continue;
      const c = makeContact(GROUND, B, v3(0, 1, 0), -p.y, v3(p.x, p.y, p.z), {
        mu: mixMu(GROUND_MU, B.mu),
